mapper.select:
select l.logistics_id, l.order_id, coalesce(l.warehouse_id, case when l.direction = 2 then o.return_warehouse_id else o.warehouse_id end) as warehouse_id, o.order_no, l.direction, l.carrier, l.tracking_no, l.source_type, l.pickup_time, l.estimated_arrive_time, l.route_status, l.abnormal_flag, l.route_available, l.route_provider, l.route_message, l.route_query_time, (select max(route.route_time) from ry_business.ry_rental_logistics_route route where route.logistics_id = l.logistics_id and route.is_delete = 0) as last_route_time, w.warehouse_name, l.fee_amount, l.update_time from ry_business.ry_rental_logistics_order l inner join ry_business.ry_rental_order o on o.tenant_id = l.tenant_id and o.member_id = l.member_id and o.order_id = l.order_id and o.is_delete = 0 left join ry_business.ry_rental_warehouse w on w.tenant_id = l.tenant_id and w.member_id = l.member_id and w.warehouse_id = coalesce(l.warehouse_id, case when l.direction = 2 then o.return_warehouse_id else o.warehouse_id end) and w.is_delete = 0 where l.tenant_id = #{tenantId} and l.member_id = #{memberId} and l.is_delete = 0
and (o.order_no like concat('%', #{query.keyword}, '%') or l.carrier like concat('%', #{query.keyword}, '%') or l.tracking_no like concat('%', #{query.keyword}, '%'))
and l.direction = #{query.direction}
and l.route_status = #{query.routeStatus}
and l.abnormal_flag = 1
and coalesce(l.warehouse_id, case when l.direction = 2 then o.return_warehouse_id else o.warehouse_id end) in
#{warehouseId}
and 1 = 0
order by l.abnormal_flag desc, l.route_query_time is null desc, l.update_time desc, l.logistics_id desc

select order_id
  from ry_business.ry_rental_order
 where tenant_id = #{tenantId}
   and member_id = #{memberId}
   and order_no = #{orderNo}
   and is_delete = 0
 limit 1

mapper.update:
update ry_business.ry_rental_logistics_route r
inner join ry_business.ry_rental_logistics_order l
  on l.logistics_id = r.logistics_id
set r.is_delete = 1
where r.logistics_id = #{logisticsId}
  and r.is_delete = 0
  and l.tenant_id = #{tenantId}
  and l.member_id = #{memberId}
  and l.is_delete = 0
